import math

state = 'UNPIN'
unpin_start_progress = None

def control(obs):
    global state, unpin_start_progress

    progress = obs['progress']['covered']
    hitch = obs['hitch_deg']

    if state == 'UNPIN':
        if unpin_start_progress is None:
            unpin_start_progress = progress
        if progress - unpin_start_progress > -2.0:
            return {'steer_deg': 25.0, 'speed_mps': 1.2, 'look_deg': 160.0}
        else:
            state = 'REVERSE'

    desired_hitch = 0.0
    target = obs.get('target', {})
    if target.get('in_sight'):
        tb = target.get('bearing_deg', 180.0)
        dev = 180.0 - tb if tb > 0 else -(180.0 + tb)
        desired_hitch = max(-25.0, min(25.0, 0.6 * dev))
    else:
        desired_hitch = 12.0

    error = hitch - desired_hitch
    target_steer = 2.5 * error
    target_steer = max(-45.0, min(45.0, target_steer))

    return {
        'steer_deg': target_steer,
        'speed_mps': -obs['speed']['default_rev'],
        'look_deg': 160.0
    }

